// Preparation only: two read-only DeepSeek GETs, one public pricing GET,
// and native Codex login status. No generation, grants or billing changes.
import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';import {loadConfig} from '../src/config/index.js';import {checkDeepSeek} from '../src/services/deepseek-connection.js';import {verifyDemoPrices} from '../src/services/demo-approval.js';import {CodexProfiles} from '../src/services/codex-profiles.js';
process.loadEnvFile('.env');const config=loadConfig(),settings=config.ai.providers.find(p=>p.id==='deepseek'),requests=[],out='docs/verification/nemotron-integration-20261107/accounts.json';
const guardedFetch=async(url,options={})=>{const u=new URL(url);if(options.method&&options.method!=='GET'||!['api.deepseek.com','api-docs.deepseek.com'].includes(u.hostname)||u.hostname==='api.deepseek.com'&&!['/models','/user/balance'].includes(u.pathname))throw Error('Read-only preparation endpoint required');requests.push({host:u.hostname,path:u.pathname,method:'GET'});return fetch(url,options);};
const result={checkedAt:new Date().toISOString(),generationRequests:0,requests,deepseek:await checkDeepSeek(settings,guardedFetch,15000),prices:null,codex:null};
try{const source='https://api-docs.deepseek.com/quick_start/pricing/',r=await guardedFetch(source,{method:'GET',redirect:'error',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Public pricing unavailable');const reader=r.body.getReader(),chunks=[];let size=0;for(;;){const p=await reader.read();if(p.done)break;size+=p.value.length;if(size>512000){await reader.cancel();throw Error('Pricing response too large');}chunks.push(p.value);}const html=Buffer.concat(chunks);result.prices={...verifyDemoPrices(html.toString('utf8')),httpStatus:r.status,checkedAt:new Date().toISOString(),sourceHash:createHash('sha256').update(html).digest('hex'),unit:'USD per million tokens, uncached peak rates',conservativeReservationUSD:(24000+4096)*0.3/1e6+4096*1.2/1e6,proposedCapUSD:0.02};}catch{result.prices={verified:false,error:'Current official pricing could not be verified. No dispatch allowed.'};}
result.configuration={model:settings.model,inputUSDPerMillion:settings.inputPrice,outputUSDPerMillion:settings.outputPrice,priceLeaseExpires:config.ai.paid.pricesVerifiedUntil||null,priceLeaseCurrentlyValid:Date.parse(config.ai.paid.pricesVerifiedUntil)>Date.now(),timeoutMs:config.studioTimeouts.deepseek};
result.codex=await new CodexProfiles().check('codex-personal',path.join(process.env.LOCALAPPDATA,'Programs/OpenAI/Codex/bin/codex.exe'),process.cwd());result.codex.allowance='UNKNOWN — native login status does not report remaining included usage';
fs.writeFileSync(out,JSON.stringify(result,null,2));console.log(JSON.stringify(result));
